nodes.text_raw:
* { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --bg-deep: #0a0e1a;
  --bg-mid: #141b2d;
  --card: rgba(22, 30, 48, 0.55);
  --fg: #f4ead5;
  --fg-soft: rgba(244, 234, 213, 0.7);
  --muted: rgba(244, 234, 213, 0.45);
  --line: rgba(244, 234, 213, 0.1);
  --warm: #ff7e5f;
  --warm-hot: #ff5e62;
  --cool: #5ec5d6;
  --cool-cold: #6a8eff;
  --gold: #f6b94d;
}

html, body {
  width: 100%;
  height: 100vh;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  background: var(--bg-deep);
  color: var(--fg);
  -webkit-font-smoothing: antialiased;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(ellipse 900px 700px at 18% 20%, rgba(255, 126, 95, 0.18) 0%, transparent 60%),
    radial-gradient(ellipse 800px 600px at 82% 80%, rgba(94, 197, 214, 0.14) 0%, transparent 60%),
    linear-gradient(135deg, #0a0e1a 0%, #141b2d 100%);
  position: relative;
}

body::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle at 50% 50%, rgba(255,255,255,0.025) 1px, transparent 1px);
  background-size: 32px 32px;
  pointer-events: none;
  mask-image: radial-gradient(ellipse at center, black 30%, transparent 75%);
  -webkit-mask-image: radial-gradient(ellipse at center, black 30%, transparent 75%);
}

.weather-card {
  width: 1100px;
  max-width: 94vw;
  background: var(--card);
  backdrop-filter: blur(24px) saturate(1.2);
  -webkit-backdrop-filter: blur(24px) saturate(1.2);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 28px;
  padding: 52px 60px;
  position: relative;
  z-index: 1;
  box-shadow:
    0 30px 100px rgba(0,0,0,0.55),
    0 0 80px rgba(255, 126, 95, 0.12),
    0 0 0 1px rgba(255,255,255,0.04) inset;
  animation: cardIn 0.8s cubic-bezier(.2,.8,.2,1);
}

@keyframes cardIn {
  from { opacity: 0; transform: translateY(20px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 44px;
}

.label {
  font-size: 11px;
  letter-spacing: 4px;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 10px;
  font-weight: 500;
}

.location-name {
  font-size: 44px;
  font-weight: 200;
  letter-spacing: -1.5px;
  line-height: 1;
}

.coords {
  font-size: 12px;
  color: var(--muted);
  margin-top: 10px;
  letter-spacing: 1.5px;
  font-variant-numeric: tabular-nums;
}

.date-block { text-align: right; }

.date-day {
  font-size: 28px;
  color: var(--fg);
  font-weight: 300;
  margin-top: 4px;
  letter-spacing: -0.5px;
}

.main-display {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
  margin-bottom: 48px;
  padding-bottom: 44px;
  border-bottom: 1px solid var(--line);
}

.temp-block {
  display: flex;
  align-items: flex-start;
  gap: 6px;
}

.temp-max {
  font-size: 172px;
  font-weight: 100;
  line-height: 0.85;
  letter-spacing: -8px;
  background: linear-gradient(135deg, var(--gold) 0%, var(--warm) 55%, var(--warm-hot) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.temp-unit {
  font-size: 38px;
  color: var(--fg-soft);
  font-weight: 200;
  margin-top: 14px;
}

.temp-meta {
  margin-top: 18px;
  display: flex;
  gap: 26px;
  font-size: 13px;
  flex-wrap: wrap;
}

.temp-meta-item {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--fg-soft);
  letter-spacing: 0.5px;
}

.temp-meta-item .dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  box-shadow: 0 0 8px currentColor;
}
.dot.max { background: var(--warm); color: var(--warm); }
.dot.min { background: var(--cool); color: var(--cool); }
.dot.range { background: var(--gold); color: var(--gold); }

.condition {
  display: flex;
  align-items: center;
  gap: 26px;
  justify-content: flex-end;
}

.condition-text { text-align: right; }

.condition-name {
  font-size: 26px;
  font-weight: 300;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
}

.condition-desc {
  font-size: 12px;
  color: var(--muted);
  letter-spacing: 1.5px;
  text-transform: uppercase;
}

.condition-icon {
  width: 104px;
  height: 104px;
  color: var(--gold);
  filter: drop-shadow(0 0 24px rgba(246, 185, 77, 0.35));
  animation: iconFloat 4s ease-in-out infinite;
}

@keyframes iconFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}

.hourly-section { position: relative; }

.hourly-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 28px;
}

.hourly-title {
  font-size: 11px;
  letter-spacing: 4px;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 500;
}

.hourly-legend {
  display: flex;
  gap: 16px;
  font-size: 11px;
  color: var(--muted);
  letter-spacing: 1.5px;
  text-transform: uppercase;
}

.legend-swatch {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.legend-swatch span {
  width: 18px;
  height: 2px;
  border-radius: 2px;
}

.chart-container {
  position: relative;
  width: 100%;
  height: 220px;
}

svg.chart {
  width: 100%;
  height: 100%;
  overflow: visible;
}

.chart-line {
  fill: none;
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 4px 16px rgba(255, 126, 95, 0.3));
  vector-effect: non-scaling-stroke;
}

.chart-dot {
  cursor: pointer;
  transition: r 0.18s, filter 0.18s;
}

.chart-hit {
  cursor: pointer;
  fill: transparent;
}

.chart-dot.active {
  r: 6;
  filter: drop-shadow(0 0 8px currentColor);
}

.chart-hover-line {
  stroke: rgba(244, 234, 213, 0.25);
  stroke-width: 1;
  stroke-dasharray: 3 4;
  opacity: 0;
  transition: opacity 0.2s;
  vector-effect: non-scaling-stroke;
}
.chart-hover-line.active { opacity: 1; }

.chart-tooltip {
  position: absolute;
  background: rgba(14, 20, 34, 0.95);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 10px;
  padding: 10px 14px;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.15s;
  transform: translate(-50%, -120%);
  white-space: nowrap;
  z-index: 10;
  box-shadow: 0 12px 32px rgba(0,0,0,0.5);
}

.chart-tooltip .t-time {
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 1.5px;
  text-transform: uppercase;
}

.chart-tooltip .t-val {
  font-size: 18px;
  font-weight: 300;
  margin-top: 2px;
  color: var(--fg);
}

.chart-tooltip .t-val .deg {
  color: var(--warm);
  margin-left: 2px;
}

.error {
  text-align: center;
  padding: 80px 20px;
}

.error-icon {
  width: 72px;
  height: 72px;
  margin: 0 auto 24px;
  color: var(--warm);
  opacity: 0.8;
}

.error h2 {
  font-size: 26px;
  font-weight: 300;
  margin-bottom: 12px;
  color: var(--fg);
  letter-spacing: -0.5px;
}

.error p {
  color: var(--muted);
  font-size: 13px;
  letter-spacing: 1px;
}

.error .hint {
  margin-top: 28px;
  font-size: 11px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: rgba(244, 234, 213, 0.3);
}

.loading {
  text-align: center;
  padding: 110px 20px;
  color: var(--muted);
  font-size: 12px;
  letter-spacing: 4px;
  text-transform: uppercase;
}

.loading-dots {
  display: inline-flex;
  gap: 6px;
  margin-left: 14px;
  vertical-align: middle;
}

.loading-dots span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--warm);
  animation: bounce 1.2s infinite;
}
.loading-dots span:nth-child(2) { animation-delay: 0.15s; }
.loading-dots span:nth-child(3) { animation-delay: 0.3s; }

@keyframes bounce {
  0%, 80%, 100% { opacity: 0.3; transform: scale(0.7); }
  40% { opacity: 1; transform: scale(1.1); }
}

.chart-grid-line {
  stroke: rgba(244, 234, 213, 0.06);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}

