function getQueryParams() {
  const params = new URLSearchParams(window.location.search);
  const latRaw = params.get('lat');
  const lonRaw = params.get('lon');
  const lat = latRaw !== null && !isNaN(parseFloat(latRaw)) ? parseFloat(latRaw) : 52.52;
  const lon = lonRaw !== null && !isNaN(parseFloat(lonRaw)) ? parseFloat(lonRaw) : 13.405;
  const name = params.get('name') || 'Berlin';
  const today = new Date().toISOString().split('T')[0];
  const date = params.get('date') || today;
  return { lat, lon, name, date };
}

function isPastDate(dateStr) {
  const today = new Date();
  today.setUTCHours(0, 0, 0, 0);
  const d = new Date(dateStr + 'T00:00:00Z');
  return d < today;
}

function formatDate(dateStr) {
  const d = new Date(dateStr + 'T00:00:00Z');
  const opts = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' };
  return d.toLocaleDateString('en-US', opts);
}

function tempColor(t) {
  if (t < 0) return '#6a8eff';
  if (t < 8) return '#5ec5d6';
  if (t < 16) return '#5ec5d6';
  if (t < 22) return '#f6b94d';
  if (t < 28) return '#ff7e5f';
  return '#ff5e62';
}

async function fetchWeather(lat, lon, date) {
  const params = new URLSearchParams({
    latitude: lat,
    longitude: lon,
    daily: 'temperature_2m_max,temperature_2m_min,weather_code',
    hourly: 'temperature_2m',
    timezone: 'UTC',
    temperature_unit: 'celsius',
    start_date: date,
    end_date: date
  });

  const endpoint = isPastDate(date) ? '/api/om/archive' : '/api/om/forecast';
  const url = `${endpoint}?${params.toString()}`;

  const res = await fetch(url);
  if (!res.ok) throw new Error(`Server returned ${res.status} ${res.statusText}`);
  return res.json();
}

function renderError(msg) {
  document.getElementById('card').innerHTML = `
    <div class="error">
      <svg class="error-icon" viewBox="0 0 100 100" fill="none" stroke="currentColor" stroke-width="2.5">
        <circle cx="50" cy="50" r="38"/>
        <line x1="50" y1="28" x2="50" y2="58" stroke-linecap="round"/>
        <circle cx="50" cy="70" r="2.2" fill="currentColor" stroke="none"/>
      </svg>
      <h2>Unable to load weather data</h2>
      <p>${msg}</p>
      <div class="hint">Check parameters and try again</div>
    </div>
  `;
}

function renderWeather(name, date, data, lat, lon) {
  const daily = data.daily;
  const hourly = data.hourly;

  if (!daily || !hourly || !Array.isArray(daily.temperature_2m_max) || daily.temperature_2m_max.length === 0) {
    renderError('No data available for the requested date.');
    return;
  }

  const tMax = daily.temperature_2m_max[0];
  const tMin = daily.temperature_2m_min[0];
  const code = daily.weather_code[0];
  const condition = weatherCodes[code] || { name: 'Unknown condition', desc: 'Code ' + code, icon: 'cloud' };

  const hours = hourly.time.map((t, i) => ({
    hour: parseInt(t.split('T')[1]),
    temp: hourly.temperature_2m[i]
  })).filter(h => !isNaN(h.temp) && h.temp !== null);

  if (hours.length === 0) {
    renderError('No hourly data available.');
    return;
  }

  const chartW = 980;
  const chartH = 220;
  const padding = { top: 40, right: 16, bottom: 36, left: 16 };
  const temps = hours.map(h => h.temp);
  const maxT = Math.max(...temps);
  const minT = Math.min(...temps);
  const range = Math.max(maxT - minT, 1);
  const innerW = chartW - padding.left - padding.right;
  const innerH = chartH - padding.top - padding.bottom;

  const points = hours.map((h, i) => {
    const x = padding.left + (i / Math.max(hours.length - 1, 1)) * innerW;
    const y = padding.top + (1 - (h.temp - minT) / range) * innerH;
    return { x, y, ...h };
  });

  let pathD = `M ${points[0].x.toFixed(2)} ${points[0].y.toFixed(2)}`;
  for (let i = 0; i < points.length - 1; i++) {
    const p0 = points[i];
    const p1 = points[i + 1];
    const cpX = (p0.x + p1.x) / 2;
    pathD += ` C ${cpX.toFixed(2)} ${p0.y.toFixed(2)}, ${cpX.toFixed(2)} ${p1.y.toFixed(2)}, ${p1.x.toFixed(2)} ${p1.y.toFixed(2)}`;
  }
  const areaD = pathD + ` L ${points[points.length-1].x.toFixed(2)} ${(chartH - padding.bottom).toFixed(2)} L ${points[0].x.toFixed(2)} ${(chartH - padding.bottom).toFixed(2)} Z`;

  const labelEvery = hours.length > 12 ? 3 : 2;
  const labelPoints = points.filter((p, i) => i % labelEvery === 0);

  const labels = labelPoints.map(p =>
    `<text x="${p.x.toFixed(2)}" y="${chartH - 12}" text-anchor="middle" fill="rgba(244,234,213,0.5)" font-size="11" letter-spacing="1">${String(p.hour).padStart(2,'0')}:00</text>`
  ).join('');

  const tempLabels = labelPoints.map(p =>
    `<text x="${p.x.toFixed(2)}" y="${(p.y - 14).toFixed(2)}" text-anchor="middle" fill="rgba(244,234,213,0.85)" font-size="11" font-weight="500">${Math.round(p.temp)}°</text>`
  ).join('');

  const dots = points.map((p, i) => {
    const isLabel = i % labelEvery === 0;
    return `
      <circle class="chart-hit" cx="${p.x.toFixed(2)}" cy="${p.y.toFixed(2)}" r="14" data-hour="${p.hour}" data-temp="${p.temp.toFixed(1)}" data-x="${p.x.toFixed(2)}" data-y="${p.y.toFixed(2)}"/>
      <circle class="chart-dot ${isLabel ? 'visible' : ''}" cx="${p.x.toFixed(2)}" cy="${p.y.toFixed(2)}" r="${isLabel ? 4 : 0}" fill="${tempColor(p.temp)}" style="color:${tempColor(p.temp)}" data-hour="${p.hour}" data-temp="${p.temp.toFixed(1)}"/>
    `;
  }).join('');

  // Gridlines at quartiles
  const gridLines = [0, 0.25, 0.5, 0.75, 1].map(f => {
    const y = padding.top + f * innerH;
    return `<line class="chart-grid-line" x1="${padding.left}" y1="${y.toFixed(2)}" x2="${chartW - padding.right}" y2="${y.toFixed(2)}"/>`;
  }).join('');

  const iconSvg = icons[condition.icon] || icons.cloud;
  const iconColor = tempColor(tMax);

  document.getElementById('card').innerHTML = `
    <div class="header">
      <div>
        <div class="label">Location</div>
        <div class="location-name">${name}</div>
        <div class="coords">${Math.abs(lat).toFixed(3)}° ${lat >= 0 ? 'N' : 'S'}  ·  ${Math.abs(lon).toFixed(3)}° ${lon >= 0 ? 'E' : 'W'}</div>
      </div>
      <div class="date-block">
        <div class="label">Date</div>
        <div class="date-day">${formatDate(date)}</div>
      </div>
    </div>

    <div class="main-display">
      <div>
        <div class="temp-block">
          <div class="temp-max">${Math.round(tMax)}</div>
          <div class="temp-unit">°C</div>
        </div>
        <div class="temp-meta">
          <div class="temp-meta-item"><span class="dot max"></span>High ${Math.round(tMax)}°</div>
          <div class="temp-meta-item"><span class="dot min"></span>Low ${Math.round(tMin)}°</div>
          <div class="temp-meta-item"><span class="dot range"></span>Range ${Math.round(tMax - tMin)}°</div>
        </div>
      </div>
      <div class="condition">
        <div class="condition-text">
          <div class="condition-name">${condition.name}</div>
          <div class="condition-desc">${condition.desc}</div>
        </div>
        <svg class="condition-icon" viewBox="0 0 100 100" style="color:${iconColor}">${iconSvg}</svg>
      </div>
    </div>

    <div class="hourly-section">
      <div class="hourly-header">
        <div class="hourly-title">Hourly Temperature</div>
        <div class="hourly-legend">
          <span class="legend-swatch"><span style="background:${tempColor(minT)}"></span>${Math.round(minT)}°</span>
          <span class="legend-swatch"><span style="background:${tempColor((minT+maxT)/2)}"></span>Mid</span>
          <span class="legend-swatch"><span style="background:${tempColor(maxT)}"></span>${Math.round(maxT)}°</span>
          <span>UTC</span>
        </div>
      </div>
      <div class="chart-container" id="chartContainer">
        <svg class="chart" viewBox="0 0 ${chartW} ${chartH}" preserveAspectRatio="none">
          <defs>
            <linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stop-color="${tempColor(tMax)}" stop-opacity="0.4"/>
              <stop offset="100%" stop-color="${tempColor(tMax)}" stop-opacity="0"/>
            </linearGradient>
            <linearGradient id="lineGrad" x1="0" y1="0" x2="1" y2="0">
              <stop offset="0%" stop-color="${tempColor(minT)}"/>
              <stop offset="50%" stop-color="${tempColor((minT + maxT) / 2)}"/>
              <stop offset="100%" stop-color="${tempColor(maxT)}"/>
            </linearGradient>
          </defs>
          ${gridLines}
          <line class="chart-hover-line" id="hoverLine" x1="0" y1="${padding.top}" x2="0" y2="${chartH - padding.bottom}"/>
          <path d="${areaD}" fill="url(#areaGrad)"/>
          <path class="chart-line" d="${pathD}" stroke="url(#lineGrad)"/>
          ${dots}
          ${tempLabels}
          ${labels}
        </svg>
        <div class="chart-tooltip" id="tooltip">
          <div class="t-time"></div>
          <div class="t-val"></div>
        </div>
      </div>
    </div>
  `;

  // Hover interactions
  const container = document.getElementById('chartContainer');
  const tooltip = document.getElementById('tooltip');
  const hoverLine = document.getElementById('hoverLine');
  const hits = container.querySelectorAll('.chart-hit');
  const allDots = container.querySelectorAll('.chart-dot');

  function activate(hit) {
    const hour = hit.dataset.hour;
    const temp = hit.dataset.temp;
    const x = parseFloat(hit.dataset.x);
    const y = parseFloat(hit.dataset.y);

    tooltip.querySelector('.t-time').textContent = `${String(hour).padStart(2,'0')}:00 UTC`;
    tooltip.querySelector('.t-val').innerHTML = `${parseFloat(temp).toFixed(1)}<span class="deg">°C</span>`;

    const svgEl = container.querySelector('svg.chart');
    const svgRect = svgEl.getBoundingClientRect();
    const scaleX = svgRect.width / chartW;
    const scaleY = svgRect.height / chartH;

    tooltip.style.left = `${x * scaleX}px`;
    tooltip.style.top = `${y * scaleY}px`;
    tooltip.style.opacity = '1';

    hoverLine.setAttribute('x1', x);
    hoverLine.setAttribute('x2', x);
    hoverLine.classList.add('active');

    allDots.forEach(d => d.classList.remove('active'));
    const matchingDot = Array.from(allDots).find(d => parseFloat(d.getAttribute('cx')) === x && parseFloat(d.getAttribute('cy')) === y);
    if (matchingDot) {
      matchingDot.setAttribute('r', 6);
      matchingDot.classList.add('active');
    }
  }

  function deactivate() {
    tooltip.style.opacity = '0';
    hoverLine.classList.remove('active');
    allDots.forEach(d => {
      d.classList.remove('active');
      const isLabel = d.classList.contains('visible');
      d.setAttribute('r', isLabel ? 4 : 0);
    });
  }

  hits.forEach(hit => {
    hit.addEventListener('mouseenter', () => activate(hit));
    hit.addEventListener('mouseleave', deactivate);
  });

  // Path drawing animation
  const path = container.querySelector('.chart-line');
  if (path) {
    const len = path.getTotalLength();
    path.style.strokeDasharray = len;
    path.style.strokeDashoffset = len;
    path.getBoundingClientRect();
    path.style.transition = 'stroke-dashoffset 1.4s cubic-bezier(.3,.8,.2,1)';
    path.style.strokeDashoffset = '0';
  }
}

async function init() {
  const { lat, lon, name, date } = getQueryParams();
  try {
    const data = await fetchWeather(lat, lon, date);
    renderWeather(name, date, data, lat, lon);
  } catch (e) {
    renderError(e.message || 'Network request failed');
  }
}

init();
